"""Public help and data notices, served without Telegram authorization or personal data."""
import os
import re
from html import escape
from urllib.parse import urlsplit


def support_contact():
    return os.getenv('SUPPORT_CONTACT', '').strip() or '@nyaaa_moe'


def public_url(page):
    base = (os.getenv('PUBLIC_SITE_URL') or os.getenv('WEBAPP_URL') or '').strip().rstrip('/')
    try:
        parsed = urlsplit(base)
    except ValueError:
        return None
    if parsed.scheme != 'https' or not parsed.netloc or parsed.username or parsed.password or parsed.query or parsed.fragment or parsed.path:
        return None
    return base + '/' + page.lstrip('/')


def bot_link():
    name = os.getenv('BOT_USERNAME', '').strip().lstrip('@')
    return 'https://t.me/' + name + '?start=menu' if re.fullmatch(r'[A-Za-z0-9_]{5,32}', name) else None


def section(slug, title, body):
    return f'<section id="{slug}"><h2>{title}</h2>{body}</section>'


def render_public_page(page):
    raw_contact = support_contact()
    contact = escape(raw_contact)
    if re.fullmatch(r'@[A-Za-z0-9_]{5,32}', raw_contact):
        contact = f'<a href="https://t.me/{raw_contact[1:]}">{contact}</a>'
    support = 'Связаться с поддержкой: ' + contact
    try:
        retention = max(1, int(os.getenv('RETENTION_DAYS', '90')))
    except ValueError:
        retention = 90
    pages = {
        'help': ('Помощь с Nyan', 'Подключение, уведомления и ответы на частые вопросы.', [
            ('start', 'Что делает бот', '<p>Nyan показывает изменения сообщений, уведомляет об удалениях и считает статистику выбранных личных чатов. Вы сами выбираете чаты при подключении. Историю до подключения бот не загружает.</p><p>Доступ открывает владелец по приглашению. Отправьте боту <code>/start</code> и передайте показанный Telegram ID тому, кто вас пригласил. После выдачи доступа нажмите «Проверить приглашение».</p>'),
            ('connect', 'Как подключить аккаунт', '<ol><li>Откройте в Telegram <strong>Настройки → Telegram для бизнеса → Чат-боты</strong>. В некоторых версиях раздел называется «Автоматизация чатов».</li><li>Выберите Nyan и разрешите нужные личные чаты. Если раздела нет, обновите Telegram и проверьте доступность бизнес-функций для вашего аккаунта.</li><li>Вернитесь в бот и нажмите <strong>«Состояние бота»</strong>.</li><li>Попросите собеседника отправить тестовое сообщение в разрешённом чате, изменить и удалить его. Проверьте, что пришли уведомления.</li></ol><figure class="connection-guide"><a href="/connect.jpg" aria-label="Открыть инструкцию подключения крупно"><img src="/connect.jpg" width="1920" height="1440" loading="lazy" alt="Подключение в Telegram: Настройки → Изменить (Edit) → Автоматизация чатов (Chat Automation) → поле Bot Username or Link."></a><figcaption>Подключение бота. Нажмите на картинку, чтобы открыть крупно. Названия и расположение пунктов могут отличаться в вашей версии Telegram.</figcaption></figure><p>Право самому удалять сообщения боту не требуется. Статус «Ждём первое сообщение» означает, что подключение есть, но Nyan ещё не получил событие из выбранных чатов.</p>'),
            ('import', 'Как добавить старую переписку', '<p>В Telegram Desktop откройте личный чат → ⋮ → Экспорт истории чата и выберите JSON. Медиа скачивать не нужно.</p><p>В Mini App: <strong>Ещё → Импорт старой переписки</strong>. Выберите свой аккаунт и result.json до 128 МБ, проверьте чат и даты, затем подтвердите добавление. Один личный чат за загрузку. Повторяющиеся сообщения не считаются дважды.</p><p>Импорт добавляет только статистику, слова и метаданные. Он не восстанавливает удалённые сообщения, прошлые версии правок или архив текстов. Служебные записи не входят в число сообщений. Полнота экспорта не гарантируется.</p>'),
            ('notifications', 'Как настроить уведомления', '<p>В разделе <strong>«Настроить уведомления»</strong> выберите правки, удаления и авторов сообщений: вы, ваши собеседники или обе стороны. По умолчанию уведомления о своих сообщениях выключены. Их можно включить кнопкой <strong>«Сообщать о моих сообщениях»</strong>; свои сообщения продолжают учитываться в статистике. На каждой кнопке написано действие, которое выполнится после нажатия.</p><p><strong>«Приостановить уведомления»</strong> прекращает доставку и убирает ещё не отправленные уведомления. При этом Nyan продолжает сохранять сообщения и обновлять статистику. Уведомления за время паузы потом не придут.</p><p>Чтобы остановить само сохранение новых сообщений, откройте <strong>«Мои данные» → «Приостановить сохранение»</strong>. Старая история останется. Сообщения за время паузы после возобновления не загрузятся.</p>'),
            ('missing', 'Почему нет уведомлений', '<p>Проверьте в «Состоянии бота», что аккаунт подключён и сообщения поступают. В настройках Telegram убедитесь, что нужный чат разрешён. Затем проверьте, что в Nyan включены уведомления, нужный тип изменений и нужный автор.</p><p>Если соединение отключено, подключите бота заново. Если сохранение приостановлено, возобновите его в «Моих данных». При сбое бот может отправить уведомление с задержкой. Не полученные ботом события восстановить нельзя.</p><p>Telegram не сообщает, кто удалил сообщение. Уведомление показывает автора исходного сообщения, а не человека, который нажал «Удалить».</p>'),
            ('stats', 'Как читать статистику', '<p>Нажмите «Открыть статистику», выберите период и аккаунт. В «Чатах» найдите собеседника и откройте его карточку. «Сводка» показывает общую активность, а «Ещё» открывает остальные разделы.</p><p>Дни считаются по московскому времени. «Всё время» означает историю, известную Nyan. Часть старых сообщений может быть учтена только в общих итогах: приложение помечает неполные данные. Пустое место на графике не всегда означает, что сообщений не было.</p><p>Если приложение просит открыть его заново, закройте окно и снова нажмите кнопку статистики в боте.</p>'),
            ('profiles', 'Что такое наблюдение за профилями', '<p>Это отдельный закрытый раздел для выбранных пользователей. Он отмечает изменения имени, username, описания и фото добавленных профилей. Обычное приглашение в Nyan не открывает этот раздел.</p><p>«Добавить профиль» начинает наблюдение с текущего состояния. «История изменений» показывает изменения после добавления. «Остановить наблюдение» прекращает новые проверки, но оставляет сохранённую историю до удаления данных.</p>'),
            ('delete', 'Как удалить данные', '<p>Откройте <strong>«Мои данные» → «Удалить мои данные…»</strong>. Прочитайте подтверждение и нажмите «Удалить данные безвозвратно». Это касается всех ваших аккаунтов в Nyan.</p><p>Бот удалит активную сохранённую историю, статистику, слова, аватарки и историю профилей и остановит новое сохранение. Уже отправленные сообщения останутся в Telegram. После возобновления статистика начнётся заново.</p><p>Обработка резервных копий описана на странице <a href="/privacy#deletion">«Данные и приватность»</a>.</p>'),
            ('support', 'Нужна помощь человека', '<p>' + support + '</p><p>Опишите, что вы ожидали и что произошло, укажите время и название раздела. Не отправляйте токен бота, ключи, сессию Telegram или полный файл настроек.</p>'),
        ]),
        'privacy': ('Данные и приватность', 'Что Nyan сохраняет, зачем это нужно и как удалить свою историю.', [
            ('summary', 'Самое главное', '<p>Вы выбираете чаты при подключении. Nyan обрабатывает новые сообщения, чтобы показывать правки, удаления и статистику. Старую переписку автоматически не загружает. Её можно добавить в статистику через JSON-импорт в Mini App.</p><p><strong>Оператор сервера имеет технический доступ к сохранённым данным.</strong> Шифрование сообщений не скрывает их от оператора, у которого есть ключ. Обычный пользователь видит только данные своих аккаунтов.</p>'),
            ('stored', 'Какие данные сохраняются', '<ul><li>Тексты и подписи сообщений, сведения об авторах и чатах, время и тип сообщения.</li><li>Полученные правки, удаления, счётчики активности, слова и статистические итоги.</li><li>Небольшие аватарки для отображения чатов.</li><li>Для отдельной закрытой группы: текущие данные добавленных профилей, история их изменений и сохранённые фото.</li></ul><p>Бот не скачивает все вложения в отдельный общий архив. Для повторной отправки медиа в уведомлениях он использует идентификаторы файлов Telegram.</p>'),
            ('retention', 'Сколько хранятся данные', f'<dl><dt>Тексты сохранённых сообщений</dt><dd>Текущая настройка сервера: {retention} дней.</dd><dt>Уведомления в очереди</dt><dd>До 7 дней.</dd><dt>Подробные события изменений</dt><dd>До 90 дней.</dd><dt>Статистические итоги, слова и дневные счётчики</dt><dd>До удаления вами. Они могут оставаться после истечения срока хранения текстов.</dd><dt>Аватарки чатов</dt><dd>Кэшируются на сутки, затем очищаются после истечения срока.</dd><dt>Закрытая история профилей и сохранённые фото</dt><dd>До 90 дней. Текущие снимки профилей остаются до удаления данных.</dd></dl><p>Содержимое успешно обработанного входящего события удаляется сразу. Его номер остаётся до 7 дней, в пределах 100 000 записей. Необработанные события находятся в ограниченной зашифрованной очереди до устранения ошибки. Служебные отметки предотвращения повторного подсчёта могут оставаться до удаления данных.</p>'),
            ('import', 'Загруженные экспорты', '<p>Для импорта статистики можно загрузить JSON одного личного чата. Тексты обрабатываются для расчёта показателей и слов, но не добавляются в архив сообщений Nyan и не вызывают уведомлений. В статистике сохраняются счётчики, частые слова и метаданные.</p><p>Временный файл на диске зашифрован. Случайный ключ хранится только в памяти процесса. Файл удаляется после обработки, отмены или 10 минут ожидания; незавершённая загрузка ограничена 3 минутами. Удаление ваших данных убирает импортированную статистику и останавливает её обработку.</p>'),
            ('protection', 'Как защищаются данные', '<p>Тексты, расчётные снимки, входящие события и очередь уведомлений шифруются AES-256-GCM. Оператор хранит ключ отдельно от публичного кода.</p><p>Имена, идентификаторы, слова, агрегаты статистики и профильные сведения остаются открытыми полями базы; изображения хранятся файлами или в кэше. Защиту диска, временных файлов и резервных копий обеспечивает оператор хостинга. Кодовое шифрование текстов не означает шифрования всего сервера.</p>'),
            ('controls', 'Чем вы управляете', '<p>В «Уведомлениях» можно приостановить доставку, сохранив сбор и статистику. В «Моих данных» можно остановить само сохранение новых сообщений, затем возобновить его. История за время остановки не загружается.</p><p>Вы также можете изменить разрешённые чаты или отключить бота в настройках Telegram Business.</p>'),
            ('deletion', 'Что происходит после удаления', '<p>После подтверждения в «Моих данных» Nyan удаляет вашу историю из активной базы, очереди и доступных приложению фото. Новое сохранение останавливается. Уже доставленные сообщения в Telegram остаются.</p><p>Минимальные идентификаторы доступа и зашифрованный журнал удалений сохраняются, чтобы старые события или восстановление копии не вернули удалённую историю.</p><p>По инструкции оператор должен хранить регулярные зашифрованные копии отдельно от рабочего диска не более 7 дней. Перед запуском восстановленной базы он обязан применить актуальный журнал удалений. Старые внешние и миграционные копии требуют отдельной очистки оператором. Физическое уничтожение всех следов на диске одним нажатием кнопки не обещается.</p>'),
            ('operator', 'Вопросы оператору', '<p>' + support + '</p><p>Уточните у оператора фактическую защиту хранилища и резервных копий, если эти условия важны для вашего использования.</p>'),
        ]),
        'terms': ('Условия использования', 'Что ожидать от Nyan и какие ограничения учитывать.', [
            ('purpose', 'Для чего нужен Nyan', '<p>Nyan помогает следить за изменениями сообщений и статистикой личных чатов, которые вы разрешили при подключении Telegram Business. Доступ выдаёт владелец по приглашению и может отозвать его.</p><p>Наблюдение за профилями открывается отдельно. Сейчас Nyan не включает новые правила автоматического удаления входящих сообщений. Сохранённые старые правила приостановлены.</p>'),
            ('choice', 'Ваши настройки', '<p>Вы выбираете подключённые чаты, уведомления и момент остановки сохранения. Учитывайте содержание переписки и интересы собеседников, когда разрешаете её обработку. Данные и доступ к ним описаны на странице <a href="/privacy">«Данные и приватность»</a>.</p>'),
            ('limits', 'Ограничения работы', '<p>Nyan учитывает только события, которые получил от Telegram. История до подключения, пропущенные события и сообщения за время остановки могут быть недоступны. Telegram не сообщает, кто именно удалил сообщение.</p><p>Доставка может задерживаться из-за ограничений Telegram, сети или остановки сервера. При сбое между отправкой и записью результата возможно повторное уведомление. Статистика может содержать неполные периоды; приложение отмечает такие случаи.</p><p>Используйте Nyan с учётом этих ограничений. Бот не заменяет гарантированный архив переписки и не обещает восстановить любое удалённое сообщение.</p>'),
            ('stop', 'Как прекратить использование', '<p>Приостановите сохранение в «Моих данных» или отключите Nyan в настройках Telegram. Чтобы удалить накопленную историю, отдельно выполните удаление в «Моих данных». Отключение соединения само по себе не удаляет старые данные.</p>'),
            ('contact', 'Связь с оператором', '<p>' + support + '</p>'),
        ]),
    }
    title, intro, content = pages[page]
    nav = ''.join(f'<a href="/{key}"' + (' aria-current="page"' if key==page else '') + f'>{label}</a>' for key,label in [('help','Помощь'),('privacy','Данные и приватность'),('terms','Условия')])
    toc = ''.join(f'<a href="#{slug}">{heading}</a>' for slug,heading,_ in content)
    body = ''.join(section(*item) for item in content)
    url = bot_link()
    back = f'<a class="bot-link" href="{escape(url,quote=True)}">Открыть Nyan в Telegram</a>' if url else '<p class="return-note">Вернитесь в чат с Nyan и отправьте /menu.</p>'
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f8f7fc"><title>{title} — Nyan message</title><link rel="icon" href="/nyan-icon.jpg"><link rel="stylesheet" href="/public.css"></head><body><a class="skip-link" href="#main">К содержимому</a><div class="page"><header><a class="brand" href="/help"><img src="/nyan-icon.jpg" width="40" height="40" alt="">Nyan message</a>{back}</header><nav aria-label="Справочные страницы">{nav}</nav><main id="main"><h1>{title}</h1><p class="intro">{intro}</p><details class="contents"><summary>На этой странице</summary><div>{toc}</div></details>{body}</main><footer><p>Обновлено 16 октября 2026</p><a href="#main">В начало страницы</a></footer></div></body></html>'''
